    var l1 := row[0];
    var r1 := row[1];
    var l2 := row[2];
    var r2 := row[3];
    steps := steps + 4;
    if l1 != l2 {
      output := output + IntToString(l1) + " " + IntToString(l2) + "\n";
      steps := steps + 4;
    } else if l1 != r2 {
      output := output + IntToString(l1) + " " + IntToString(r2) + "\n";
      steps := steps + 4;
    } else if r1 != l2 {
      output := output + IntToString(r1) + " " + IntToString(l2) + "\n";
      steps := steps + 4;
    } else if r1 != r2 {
      output := output + IntToString(r1) + " " + IntToString(r2) + "\n";
      steps := steps + 4;
    } else {
      steps := steps + 1;
    }
    i := i + 1;
    steps := steps + 1;
  }
}

